The real Spring structure, showing both the trap and the fix:

```java
// ─── File: src/main/java/com/bank/readonly/service/FixedAccountService.java ───
package com.bank.readonly.service;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

// DO NOT put @Transactional(readOnly = true) on the CLASS of a service that writes.
@Service
public class FixedAccountService {
    private final AccountRepository repo;
    public FixedAccountService(AccountRepository repo) { this.repo = repo; }

    // Query method: readOnly is correct and gives a real optimization.
    @Transactional(readOnly = true)
    public BigDecimal getBalance(String id) {
        return repo.findById(id).orElseThrow().getBalance();
    }

    // Write method: writable @Transactional. If a class-level readOnly existed,
    // this method-level annotation OVERRIDES it so the UPDATE actually flushes.
    @Transactional
    public void transfer(String from, String to, BigDecimal amount) {
        var f = repo.findById(from).orElseThrow();
        var t = repo.findById(to).orElseThrow();
        if (f.getBalance().compareTo(amount) < 0)
            throw new IllegalStateException("Insufficient balance");
        f.debit(amount); t.credit(amount);
        // No explicit save needed: AUTO flush writes the dirty entities at commit.
    }
}
